import re
from decimal import Decimal

# All arithmetic here is exact integer arithmetic on cents, or inspection of
# Decimal's sign/digits/exponent. Nothing depends on the caller's decimal
# context precision or rounding, and the global context is never touched.

MAX_AMOUNT_CENTS = 100_000_000  # 1000000.00
_MAX_WHOLE_UNITS = 1_000_000
_STRING_AMOUNT = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def parse_cents(value):
    """Validate an amount and return it as an exact integer number of cents."""
    if isinstance(value, bool):
        raise ValueError("amount must not be a bool")
    if isinstance(value, int):
        if value <= 0 or value > _MAX_WHOLE_UNITS:
            raise ValueError("amount must be greater than 0 and at most 1000000.00")
        return value * 100
    if isinstance(value, str):
        if _STRING_AMOUNT.fullmatch(value) is None:
            raise ValueError("amount string is not a valid decimal number")
        value = Decimal(value)
    elif not isinstance(value, Decimal):
        raise ValueError(f"unsupported amount type: {type(value).__name__}")
    return _decimal_to_cents(value)


def _decimal_to_cents(value):
    if not value.is_finite():
        raise ValueError("amount must be finite")
    if value.is_zero():
        raise ValueError("amount must be greater than 0")
    sign, digits, exponent = value.as_tuple()
    if sign:
        raise ValueError("amount must be greater than 0")
    # adjusted() is the exponent of the leading digit; > 6 means |value| >= 10**7.
    # Checking this first also keeps the power computed below small.
    if value.adjusted() > 6:
        raise ValueError("amount must be at most 1000000.00")
    coefficient = "".join(map(str, digits))
    significant = coefficient.rstrip("0")
    exponent += len(coefficient) - len(significant)
    # value == int(significant) * 10**exponent, and the last digit is nonzero.
    if exponent < -2:
        raise ValueError("amount is not exactly representable in cents")
    cents = int(significant) * 10 ** (exponent + 2)
    if cents > MAX_AMOUNT_CENTS:
        raise ValueError("amount must be at most 1000000.00")
    return cents


def cents_to_amount(cents):
    """Return an exact Decimal with exponent -2 for an integer number of cents."""
    whole, fraction = divmod(cents, 100)
    return Decimal(f"{whole}.{fraction:02d}")


def parse_amount(value):
    return cents_to_amount(parse_cents(value))


def format_amount(value):
    return format(value, ".2f")
EOF
