from fractions import Fraction
sys.path.insert(0, "/workspace")
from src.money import parse_cents, parse_amount, format_amount
from src.api import make_invoice

GRAMMAR = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")
MAX = Fraction(1000000)

def reference(v):
    """Return cents if v is valid, else None. Uses exact Fraction math only."""
    if isinstance(v, bool): return None
    if isinstance(v, int): f = Fraction(v)
    elif isinstance(v, str):
        if GRAMMAR.fullmatch(v) is None: return None
        f = Fraction(v)
    elif isinstance(v, Decimal):
        if not v.is_finite(): return None
        f = Fraction(v)
    else: return None
    if f <= 0 or f > MAX: return None
    c = f * 100
    if c.denominator != 1: return None
    return int(c)

rng = random.Random(12345)
ALPHABET = "0123456789"

def rand_digits(n):
    return "".join(rng.choice(ALPHABET) for _ in range(n))

def rand_string():
    kind = rng.random()
    sign = rng.choice(["", "", "", "+", "-"])
    ip = rand_digits(rng.randint(1, 9)) if rng.random() < 0.9 else ""
    if rng.random() < 0.3: ip = "0" * rng.randint(0, 3) + ip
    s = sign + ip
    if rng.random() < 0.7:
        s += "." + rand_digits(rng.randint(0, 5))
    if kind < 0.05: s += rng.choice(["e3", "E-2", " ", "\n", "_", "."])
    if kind > 0.97: s = s.replace("1", "\u0661")
    return s

def rand_decimal():
    sign = rng.choice([0, 0, 0, 1])
    n = rng.randint(1, 12)
    digs = tuple(int(c) for c in rand_digits(n))
    if rng.random() < 0.1: digs = (0,) * rng.randint(1, 4) + digs
    exp = rng.choice(range(-8, 4)) if rng.random() < 0.9 else rng.randint(-999999, 999999)
    return Decimal((sign, digs, exp))

def rand_value():
    r = rng.random()
    if r < 0.45: return rand_string()
    if r < 0.8: return rand_decimal()
    if r < 0.9: return rng.randint(-5, 1000005)
    return rng.choice([1.0, True, None, b"1", float("nan"), Decimal("NaN"), Decimal("-Infinity"), Decimal("sNaN")])

def run(v):
