                if len(mismatch) > 10: break
        flags_set = {k for k, x in ctx.flags.items() if x}
        if flags_set: print("flags set in caller ctx:", flags_set)
print("checked", checked, "mismatches", len(mismatch))
for m in mismatch[:10]: print(m)
print("global context unchanged:", repr(getcontext()) == before)

# Accepted results must be exponent -2 and exact under any precision.
accepted = 0
for prec in [1, 3, 28]:
    with localcontext(Context(prec=prec)):
        for _ in range(20000):
            v = rand_string() if rng.random() < 0.5 else rand_decimal()
            try: d = parse_amount(v)
            except ValueError: continue
            accepted += 1
            assert d.as_tuple().exponent == -2, (v, d)
            assert Fraction(d) == Fraction(reference(v), 100), (v, d)
print("accepted parse results verified:", accepted)

# make_invoice sums must equal exact Fraction sums (under low precision).
ok = 0
for prec in [1, 3, 28]:
    with localcontext(Context(prec=prec)):
        for _ in range(3000):
            n = rng.randint(0, 40)
            items = [rng.choice([f"{rng.randint(0,9999)}.{rng.randint(0,99):02d}",
                                 Decimal(f"{rng.randint(1,9999)}E-2")]) for _ in range(n)]
            exact = sum((Fraction(str(x)) if isinstance(x, str) else Fraction(x) for x in items), Fraction(0))
            try:
                out = make_invoice(items)
            except ValueError:
                assert exact > MAX, (items, exact)
                continue
            assert out == {"total": f"{float(exact):.2f}" if False else f"{int(exact*100)//100}.{int(exact*100)%100:02d}", "count": n}, (items, out)
            ok += 1
print("make_invoice sums verified:", ok)
print("global context unchanged after all:", repr(getcontext()) == before)
